contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 guess, uint amount) public payable {
        // lockInGuess with a wrong value must revert
        bool lockReverted;
        if (amount != 1 ether) {
            try c.lockInGuess{value: amount}(guess) { lockReverted = false; } catch { lockReverted = true; }
        } else {
            lockReverted = false;
        }
        // settle must revert since no successful lock exists
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }
        assert((amount != 1 ether ? lockReverted : true) && settleReverted);
    }
    receive() external payable {}
}

