contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 g1, bytes32 g2, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= 2 ether);

        uint balBefore = address(c).balance;

        c.lockInGuess{value: amount}(g1);
        c.settle();
        // After settle of a losing guess, the guess slot is free again:
        c.lockInGuess{value: amount}(g2);

        // settle again must NOT revert (block already passed since lockInGuess
        // records block+1 and the previous settle advanced the chain) unless
        // it's a same-block call; instead verify the reset rule directly:
        // a fresh lockInGuess succeeded above, so settle from this fresh guess
        // in the next block... we can't advance blocks; use the clearing rule:
        // the fact that the second lockInGuess did not revert proves settle
        // cleared the previous guess, and the contract balance is unchanged
        // for losing guesses.
        assert(address(c).balance == balBefore);
    }

    receive() external payable {}
}

